window.MG_LAZY_DATA["data/lazy/courses/b102-e8a3f3644a993b1f.json"]={sha256:"e8a3f3644a993b1f4264f0df2c520147f9dfd2c832c5e159dde0e576565713ba",value:{"id":"b102","category":"underground","kind":"course","status":"guided","contentStatus":"reviewable-educational-curriculum","depth":4,"languageCoverage":["zh-TW","en"],"sourceIds":["v6-channel-infrastructure","v6-channel-tbm","v6-channel-construction"],"stages":[{"id":"b102-stage01","order":1,"steps":[{"id":"b102-v6-01","sequence":1,"order":1,"sourceIds":["v6-channel-tbm","v6-channel-construction"],"simulationOnly":true,"estimatedMinutes":20,"prerequisiteIds":[],"title":"建立地層與路線剖面","titleEn":"Build a ground–alignment section","objective":"分開已觀測地層與推估延伸。","objectiveEn":"Separate observed strata from inferred continuity.","instruction":"自繪兩岸及海床，將白堊泥灰岩畫成有厚度的帶狀層。以實線代表假設鑽孔位置、虛線表示孔間推論，另標出可能含水或破碎區。","instructionEn":"Sketch both coasts and seabed with a chalk-marl band. Mark hypothetical boreholes with solid symbols and inferred continuity with dashed lines; add potentially wet or fractured zones.","observation":"觀察最短直線是否始終位於選定地層內。","observationEn":"Check whether the shortest straight alignment stays inside the selected layer.","failure":"把「主要穿越某地層」誤解成全線均質且不會滲水。","failureEn":"Treating a dominant stratum as proof of uniform, watertight conditions everywhere.","check":"剖面須有觀測／推論圖例及兩處需補充調查的位置。","checkEn":"Include an observation/inference key and two locations needing further investigation.","knowledge":[{"id":"b102-v6-01-k1","title":"地層追蹤","titleEn":"Stratum following","text":"路線可以為了維持較合適地層而調整，不必是兩點最短連線。","textEn":"Alignment may follow favorable ground rather than the shortest line between two points."},{"id":"b102-v6-01-k2","title":"局部差異","titleEn":"Local variation","text":"斷層、褶皺和含水差異會使同名岩層的施工表現不同。","textEn":"Faults, folding and water conditions can change behavior within a named rock layer."}],"quiz":{"options":["標成推論並列出驗證需求","延用最近鑽孔結果當成全段實測","從剖面刪掉不確定區"],"optionsEn":["As an inference with a verification need","Treat the nearest borehole as measurement of the whole interval","Remove the uncertain area from the section"],"answer":0,"question":"鑽孔間出現未確認的構造，應如何標記？","questionEn":"How should an unconfirmed feature between boreholes be shown?","explanation":"地質模型應保留不確定性，讓後續觀察能修正它。","explanationEn":"A geological model should preserve uncertainty so subsequent observations can revise it."}},{"id":"b102-v6-02","sequence":2,"order":2,"sourceIds":["v6-channel-tbm","v6-channel-construction"],"simulationOnly":true,"estimatedMinutes":20,"prerequisiteIds":["b102-v6-01"],"title":"連結兩岸測量基準","titleEn":"Connect survey references on both shores","objective":"理解長距離對向掘進的基準一致性。","objectiveEn":"Understand reference consistency in long opposing drives.","instruction":"畫出地面控制網、井下傳遞點與隧道導線的關係。用自設兩岸座標示例，先核對單位、方向與高程基準，再比較預期會合位置。","instructionEn":"Diagram surface controls, underground transfer points and tunnel traverses. With invented coordinates from both shores, reconcile units, orientation and height datum before comparing predicted meeting positions.","observation":"比較共同偏移和兩側相向軸線不一致造成的不同結果。","observationEn":"Compare a common offset with disagreement between opposing drive axes.","failure":"未統一高程基準，就把兩側標高差當成施工誤差。","failureEn":"Treating height differences as construction error before reconciling datums.","check":"交付一張基準對照表及一個可重現的示例閉合檢查。","checkEn":"Submit a reference table and a reproducible example closure check.","knowledge":[{"id":"b102-v6-02-k1","title":"基準傳遞","titleEn":"Reference transfer","text":"地面控制需經過可追溯的傳遞才能用於地下方向判讀。","textEn":"Surface control must be transferred traceably before underground directions can be interpreted."},{"id":"b102-v6-02-k2","title":"誤差累積","titleEn":"Error accumulation","text":"長距離測量的小方向誤差可能累積成明顯位置差。","textEn":"Small directional errors over long distances can accumulate into substantial positional differences."}],"quiz":{"options":["立即修改襯砌環直徑","單位、基準面及控制點版本","只採用數字較小的一組"],"optionsEn":["Immediately change lining-ring diameter","Units, datum and control-point versions","Use whichever numbers are smaller"],"answer":1,"question":"兩隊高程數字不一致時，第一項核對是什麼？","questionEn":"Two teams report different elevations. What should be checked first?","explanation":"先確定數據在同一參考系，才能判斷幾何偏差。","explanationEn":"Data must share a reference system before geometric discrepancies are assessed."}},{"id":"b102-v6-03","sequence":3,"order":3,"sourceIds":["v6-channel-tbm","v6-channel-construction"],"simulationOnly":true,"estimatedMinutes":20,"prerequisiteIds":["b102-v6-02"],"title":"選擇開挖配置的證據","titleEn":"Identify evidence for excavation configuration","objective":"把機台功能與地層及地下水問題配對。","objectiveEn":"Match machine functions to ground and groundwater questions.","instruction":"建立硬度、裂隙、含水與出碴四列需求表，分別說明刀盤、工作面支承、密封與運輸的角色。比較英法兩側條件可能不同的理由，不填操作壓力。","instructionEn":"Create a table for strength, fractures, water and spoil handling; identify cutting, face support, sealing and transport roles. Explain why the two shores may need different configurations without specifying operating pressures.","observation":"觀察「能切削岩石」與「能管理水及出碴」是否是不同能力。","observationEn":"Distinguish ability to cut rock from ability to manage water and spoil.","failure":"只以隧道直徑挑選機台，忽略地層與水壓條件。","failureEn":"Selecting a machine by tunnel diameter alone while ignoring ground and water conditions.","check":"每項功能至少連到一項地質證據或待調查事項。","checkEn":"Link each function to geological evidence or an investigation need.","knowledge":[{"id":"b102-v6-03-k1","title":"適地配置","titleEn":"Ground-specific configuration","text":"同一工程可採用不同配置，以回應各段地層與地下水差異。","textEn":"One project may use different configurations to address sectional ground and groundwater differences."},{"id":"b102-v6-03-k2","title":"連續物流","titleEn":"Continuous logistics","text":"切削、出碴與環片供應互相制約；單一速度不能代表整體能力。","textEn":"Cutting, spoil removal and segment supply constrain one another; one speed does not represent total capability."}],"quiz":{"options":["直徑相同就必須使用相同配置","只需改變列車速度","工作面支承與密封需求仍可能不同"],"optionsEn":["Equal diameter requires identical configuration","Only train speed needs changing","Face-support and sealing requirements may still differ"],"answer":2,"question":"兩段隧道直徑相同但含水條件不同，哪個結論合理？","questionEn":"Two sections share a diameter but differ in water conditions. Which conclusion is reasonable?","explanation":"直徑只是幾何要求；地下水和地層決定另外的功能需求。","explanationEn":"Diameter defines geometry; ground and groundwater impose additional functional requirements."}},{"id":"b102-v6-04","sequence":4,"order":4,"sourceIds":["v6-channel-tbm","v6-channel-construction"],"simulationOnly":true,"estimatedMinutes":20,"prerequisiteIds":["b102-v6-03"],"title":"用開挖觀察修訂地質模型","titleEn":"Update the ground model from excavation observations","objective":"建立預測與現地觀察不一致時的判讀流程。","objectiveEn":"Define a response when predictions and field observations disagree.","instruction":"自行寫三則示例觀察：出碴性質改變、滲水增加、測量方向偏移。分別列出可能機制、需補查紀錄與模型要修訂的欄位。","instructionEn":"Invent three observations: changed spoil, increased ingress and a survey-direction shift. For each, list candidate mechanisms, records to check and model fields to revise.","observation":"注意相同表徵可以有地質、設備或量測等不同原因。","observationEn":"Recognize that the same symptom may have geological, equipment or measurement causes.","failure":"因原模型標示低透水，就把新增滲水當成量測錯誤刪除。","failureEn":"Discarding increased ingress as measurement error because the original model predicts low permeability.","check":"至少保留兩種競爭假說，並寫出可區分它們的證據。","checkEn":"Retain at least two competing explanations and evidence that could distinguish them.","knowledge":[{"id":"b102-v6-04-k1","title":"觀察回饋","titleEn":"Observational feedback","text":"地質預測應接受新證據檢驗；模型不是現地狀態的保證。","textEn":"Geological predictions must be tested against new evidence; a model does not guarantee field conditions."},{"id":"b102-v6-04-k2","title":"可區分證據","titleEn":"Discriminating evidence","text":"有用的補查應能讓不同假說產生不同預期結果。","textEn":"Useful follow-up evidence produces different expected results under competing explanations."}],"quiz":{"options":["保留原版本，加入新觀察並重新評估","只保留原先最有利的假設","把兩種現象平均成一個正常值"],"optionsEn":["Preserve the old version, add observations and reassess","Retain only the original favorable assumption","Average both symptoms into a normal value"],"answer":0,"question":"出碴變化與新滲水同時發生時，應如何處理模型？","questionEn":"Spoil changes and new water ingress occur together. How should the model be treated?","explanation":"版本化修訂保留決策依據，並讓新增證據改變推論。","explanationEn":"Versioned revision preserves decision context while allowing new evidence to change conclusions."}}],"title":"地質、測量與開挖","titleEn":"Geology, survey and excavation","description":"把預期地層、實際觀察與開挖配置建立可修訂的對照。","descriptionEn":"Build a revisable comparison between expected ground, observations and excavation configuration."},{"id":"b102-stage02","order":2,"steps":[{"id":"b102-v6-05","sequence":5,"order":1,"sourceIds":["v6-channel-construction"],"simulationOnly":true,"estimatedMinutes":20,"prerequisiteIds":["b102-v6-04"],"title":"檢查襯砌環與接縫","titleEn":"Review lining rings and joints","objective":"分清承載、防水與幾何接合證據。","objectiveEn":"Separate evidence for load support, water control and geometric fit.","instruction":"畫一圈分片襯砌及相鄰兩環，標記接縫、接觸面與可能漏水路徑。建立環片識別、位置、缺損和接縫觀察的記錄欄位。","instructionEn":"Draw a segmented ring and two adjacent rings, marking joints, contacts and potential ingress paths. Define records for segment identity, location, defects and joint observations.","observation":"比較環片本體完整與接縫完整是否能互相替代。","observationEn":"Ask whether sound segment bodies and sound joints provide interchangeable evidence.","failure":"環片外表沒有裂縫，就認定所有接縫都止水良好。","failureEn":"Assuming every joint is watertight because segment faces have no visible cracks.","check":"為承載、幾何、防水各列一種不同的檢核證據。","checkEn":"Name distinct evidence for support, geometry and water control.","knowledge":[{"id":"b102-v6-05-k1","title":"系統接縫","titleEn":"System joints","text":"襯砌不是孤立環片的集合；環內與環間接合會影響整體性能。","textEn":"Lining behavior depends on within-ring and between-ring joints, not only isolated segments."},{"id":"b102-v6-05-k2","title":"位置追溯","titleEn":"Location traceability","text":"缺陷紀錄須能回到具體環號與方位，才能比較後續變化。","textEn":"Defect records need ring identity and orientation to support later comparisons."}],"quiz":{"options":["全隧道環片總數","同環號、方位及時間的觀察序列","未註位置的零散照片"],"optionsEn":["Total number of tunnel segments","Observations with matching ring, orientation and timestamps","Unlocated photographs"],"answer":1,"question":"哪項記錄最適合追蹤接縫漏水是否擴大？","questionEn":"Which record best tracks whether joint leakage is spreading?","explanation":"可定位、可比較的紀錄才支持變化判斷。","explanationEn":"Located and comparable records support judgments about change."}},{"id":"b102-v6-06","sequence":6,"order":2,"sourceIds":["v6-channel-infrastructure","v6-channel-construction"],"simulationOnly":true,"estimatedMinutes":20,"prerequisiteIds":["b102-v6-05"],"title":"區分漏水來源與排水路徑","titleEn":"Distinguish ingress sources from drainage paths","objective":"解釋抽排能力不等於止水成功。","objectiveEn":"Explain why pumping capacity does not prove successful water exclusion.","instruction":"自繪接縫、集水溝、集水井和抽排出口，分別用箭頭表示外水進入與收集輸送。以示例時間表比較降雨、漏水位置及抽排量。","instructionEn":"Sketch joints, drains, sumps and discharge, using different arrows for water ingress and collection. Compare rainfall, leak locations and pumping in an invented timeline.","observation":"觀察集水量變化可能來自入流改變，也可能來自排水路徑堵塞。","observationEn":"Changes in collected flow may reflect altered inflow or blocked drainage routes.","failure":"抽水機仍運轉就推論沒有漏水，或流量下降就推論問題改善。","failureEn":"Inferring no ingress because pumps run, or improvement because measured flow falls.","check":"指出兩種使觀測流量下降的不同情境與辨別資料。","checkEn":"Identify two different causes of reduced measured flow and evidence distinguishing them.","knowledge":[{"id":"b102-v6-06-k1","title":"入流與輸送","titleEn":"Inflow versus conveyance","text":"滲入隧道的水與被量測到的排水，可能因蓄積或堵塞而不同。","textEn":"Ingress and measured drainage can differ because of storage or obstruction."},{"id":"b102-v6-06-k2","title":"水量平衡","titleEn":"Water balance","text":"在有明確時間範圍的模型中，入流、出流和蓄積須互相一致。","textEn":"In a time-bounded model, inflow, outflow and storage change must be consistent."}],"quiz":{"options":["只確認供電存在，便排除所有排水問題","直接宣告外水已減少","收集及輸送路徑是否受阻"],"optionsEn":["Confirm supply power and rule out all drainage problems","Immediately conclude external ingress has decreased","Whether collection or conveyance is obstructed"],"answer":2,"question":"排水量下降但局部積水升高，最應檢查什麼？","questionEn":"Drainage flow falls while local ponding rises. What most needs checking?","explanation":"流量與積水相反變化提示輸送問題，需核查路徑和量測。","explanationEn":"Opposing flow and ponding trends suggest a conveyance issue requiring route and measurement checks."}},{"id":"b102-v6-07","sequence":7,"order":3,"sourceIds":["v6-channel-infrastructure"],"simulationOnly":true,"estimatedMinutes":20,"prerequisiteIds":["b102-v6-06"],"title":"辨認三條隧道的功能","titleEn":"Distinguish the three tunnel roles","objective":"將交通、維護與避難功能在圖中分開。","objectiveEn":"Separate traffic, maintenance and refuge functions on a diagram.","instruction":"自繪兩條行車隧道和中央服務隧道，再加入聯絡通道。用三種線型表示列車路線、維護通行與示意撤離方向，避免填入真實緊急操作命令。","instructionEn":"Sketch two running tunnels and a central service tunnel with cross-passages. Use distinct line styles for trains, maintenance and illustrative evacuation, without issuing real emergency instructions.","observation":"觀察聯絡通道與供列車換線的橫渡洞室是否是不同構造。","observationEn":"Distinguish pedestrian/service cross-passages from rail crossover caverns.","failure":"把服務隧道畫成第三條正常載客鐵路。","failureEn":"Drawing the service tunnel as a third regular passenger railway.","check":"圖例應能一眼分辨三種功能與兩種橫向連接。","checkEn":"The key must distinguish the three functions and the two types of lateral connection.","knowledge":[{"id":"b102-v6-07-k1","title":"功能隔離","titleEn":"Functional separation","text":"中央服務隧道提供維護與緊急支援，與行車隧道用途不同。","textEn":"The central service tunnel supports maintenance and emergencies rather than normal rail traffic."},{"id":"b102-v6-07-k2","title":"連接類型","titleEn":"Connection types","text":"聯絡通道服務人員移動；橫渡洞室則提供列車跨線能力。","textEn":"Cross-passages support movement of people; crossover caverns allow trains to change running tunnels."}],"quiz":{"options":["設有軌道的橫渡洞室","一般人行聯絡通道","服務隧道內的排水溝"],"optionsEn":["A rail crossover cavern","An ordinary pedestrian cross-passage","A service-tunnel drain"],"answer":0,"question":"需要列車從一條行車隧道移到另一條時，對應哪個構造？","questionEn":"Which structure allows a train to change from one running tunnel to the other?","explanation":"不同橫向連接有不同尺寸和用途，不能在系統圖上混用。","explanationEn":"Different lateral connections serve different functions and must not be conflated."}},{"id":"b102-v6-08","sequence":8,"order":4,"sourceIds":["v6-channel-infrastructure","v6-channel-construction"],"simulationOnly":true,"estimatedMinutes":20,"prerequisiteIds":["b102-v6-07"],"title":"讀懂服務隧道壓差概念","titleEn":"Interpret service-tunnel pressure differences","objective":"理解保護空間與門、通風的相互依賴。","objectiveEn":"Understand dependencies among protected space, doors and ventilation.","instruction":"以兩個箱體代表服務與行車隧道，畫出正常示意氣流和門開啟時的可能路徑。列出判斷氣流方向需要的資料，不自行設定火災排煙程序。","instructionEn":"Represent service and running tunnels as two boxes. Sketch intended airflow and possible paths when a door opens. List data needed to judge flow without defining fire-smoke operating procedures.","observation":"注意風機狀態、壓差與門的位置並非同一個訊號。","observationEn":"Fan status, pressure difference and door position are different signals.","failure":"只因風機顯示開啟，就認定保護空間一定維持壓差。","failureEn":"Assuming a protected space maintains pressure simply because a fan indicates running.","check":"列出至少三個互相核對的狀態或觀察量。","checkEn":"List at least three states or observations to cross-check.","knowledge":[{"id":"b102-v6-08-k1","title":"壓差屏障","titleEn":"Pressure barrier","text":"適當的壓差可引導氣流；實際效果仍受開口與系統狀態影響。","textEn":"Pressure differences can direct flow; openings and system state affect actual performance."},{"id":"b102-v6-08-k2","title":"功能驗證","titleEn":"Functional verification","text":"設備運转訊號只能證明部分狀態，不能代替完整功能證據。","textEn":"A running indication establishes only part of the state, not complete functional performance."}],"quiz":{"options":["忽略壓差，因馬達已運轉","核對開口、氣流及感測狀態","立即認定所有門都關妥"],"optionsEn":["Ignore pressure because motors are running","Check openings, airflow and sensor state","Assume all doors are properly closed"],"answer":1,"question":"風機開啟但保護區壓差不足，哪個判斷較合理？","questionEn":"Fans run but protected-zone pressure is insufficient. Which judgment is sound?","explanation":"保護功能依賴整體狀態，必須把設備與環境證據合看。","explanationEn":"Protection depends on system state, so equipment and environmental evidence must be combined."}}],"title":"襯砌與三隧道介面","titleEn":"Lining and three-bore interfaces","description":"追蹤環片接合、排水與聯絡通道在不同狀態的功能。","descriptionEn":"Trace segment joints, drainage and cross-passages under different system states."},{"id":"b102-stage03","order":3,"steps":[{"id":"b102-v6-09","sequence":9,"order":1,"sourceIds":["v6-channel-infrastructure"],"simulationOnly":true,"estimatedMinutes":20,"prerequisiteIds":["b102-v6-08"],"title":"整理軌道與機電淨空","titleEn":"Coordinate track and service clearances","objective":"看出斷面配置中的安裝與維護衝突。","objectiveEn":"Identify installation and maintenance conflicts in a cross-section.","instruction":"在自繪圓形斷面放入列車包絡、步道、電車線、冷卻管與電纜。再畫一個設備維護所需空間，以虛線標記尚無尺寸資料的部分。","instructionEn":"Place a train envelope, walkway, catenary, cooling pipes and cables in a circular sketch. Add maintenance space and use dashed boundaries where dimensional evidence is missing.","observation":"比較「裝得下」與「仍可檢查、撤離和維護」是否不同。","observationEn":"Distinguish physical fit from retained inspection, egress and maintenance access.","failure":"只畫設備外形，忽略人員通行及拆換路徑。","failureEn":"Drawing equipment outlines without access or replacement paths.","check":"找出兩個潛在介面衝突並列明需向哪個專業取得資料。","checkEn":"Identify two potential conflicts and the disciplines that must provide missing data.","knowledge":[{"id":"b102-v6-09-k1","title":"包絡介面","titleEn":"Envelope interfaces","text":"設備配置須同時考慮車輛動態、結構和通行空間。","textEn":"Equipment layout must account for vehicle motion, structure and access together."},{"id":"b102-v6-09-k2","title":"維護空間","titleEn":"Maintenance space","text":"正常運轉不碰撞，不等於能安全拆換或檢查設備。","textEn":"Collision-free operation does not establish that equipment can be inspected or replaced safely."}],"quiz":{"options":["是，唯一條件是不碰列車","只要管線顏色不同即可","尚未，通行與維護需求仍未滿足"],"optionsEn":["Yes; avoiding the train is the only condition","Yes, if the pipe has a different color","No; access and maintenance requirements remain unresolved"],"answer":2,"question":"一條新管線不碰列車但占用步道，是否已完成介面檢核？","questionEn":"A new pipe avoids the train but occupies the walkway. Is interface review complete?","explanation":"斷面有多種功能包絡，不能只檢查車輛外形。","explanationEn":"The cross-section contains multiple functional envelopes, not only a train outline."}},{"id":"b102-v6-10","sequence":10,"order":2,"sourceIds":["v6-channel-infrastructure"],"simulationOnly":true,"estimatedMinutes":20,"prerequisiteIds":["b102-v6-09"],"title":"檢查供電與服務依賴","titleEn":"Review power and service dependencies","objective":"說明冗餘電源不等於所有設備都無中斷。","objectiveEn":"Explain why redundant supplies do not prove uninterrupted service for every load.","instruction":"畫出兩岸電源、供電分段及列車、排水、照明三類負載。以紙上情境移除一個來源，標記哪些功能仍需切換與控制證據。","instructionEn":"Diagram power from both shores, supply sections and train, drainage and lighting loads. Remove one source in a paper scenario and mark functions requiring transfer and control evidence.","observation":"比較電源存在、路徑可用與末端設備運轉三種狀態。","observationEn":"Distinguish source availability, path availability and operation of the final device.","failure":"把圖上有兩個電源直接視為所有故障情況都有備援。","failureEn":"Treating two drawn power sources as proof of redundancy for every failure case.","check":"為一個負載畫出完整替代路徑，並列一個共同失效點的疑問。","checkEn":"Trace an alternative path to one load and identify a possible common failure point.","knowledge":[{"id":"b102-v6-10-k1","title":"端到端功能","titleEn":"End-to-end function","text":"備援需要從來源到負載的完整可用路徑。","textEn":"Redundancy requires a complete available path from source to load."},{"id":"b102-v6-10-k2","title":"共同依賴","titleEn":"Shared dependencies","text":"兩條供電路徑仍可能共用控制、保護或連接設備。","textEn":"Two supply paths may still share control, protection or connection equipment."}],"quiz":{"options":["替代來源到排水設備的整條路徑是否可用","只核對備援來源額定容量，不追蹤配電路徑","以其他負載正常推論排水設備必定可用"],"optionsEn":["Is the complete alternative path to drainage equipment available?","Check backup source rating without tracing distribution","Infer drainage availability because other loads work"],"answer":0,"question":"確認排水備援時，哪個問題最重要？","questionEn":"Which question matters most when verifying drainage backup?","explanation":"功能驗證必須追到負載，不能停在上游電源。","explanationEn":"Verification must reach the load rather than stop at the upstream source."}},{"id":"b102-v6-11","sequence":11,"order":3,"sourceIds":["v6-channel-infrastructure"],"simulationOnly":true,"estimatedMinutes":20,"prerequisiteIds":["b102-v6-10"],"title":"組織維護占用與復歸證據","titleEn":"Organize maintenance possession and return evidence","objective":"辨認施工完成與恢復運行間的交接責任。","objectiveEn":"Distinguish completion of work from authorization to resume service.","instruction":"建立示意交接表，含區段、受影響設備、隔離狀態、檢查結果及未結案項。用「換線維護」桌上情境辨認交通與設備團隊的交界，不模擬真實控制指令。","instructionEn":"Build an illustrative handover sheet with section, affected equipment, isolation state, checks and open items. Use a crossover-maintenance tabletop scenario to identify team interfaces without simulating real control commands.","observation":"觀察工件安裝完成是否仍有功能測試與文件核對未完成。","observationEn":"Notice whether physical completion still leaves functional tests or document reconciliation pending.","failure":"以工時結束代替設備復歸與路線交接確認。","failureEn":"Treating the end of a work shift as confirmation of equipment restoration and route handover.","check":"將施工完成、測試完成與授權狀態分成獨立欄位。","checkEn":"Keep work completion, test completion and authorization state in separate fields.","knowledge":[{"id":"b102-v6-11-k1","title":"狀態交接","titleEn":"State handover","text":"跨班或跨專業交接應描述實際設備狀態及尚未解除的限制。","textEn":"Cross-shift or cross-discipline handover must describe actual equipment state and remaining restrictions."},{"id":"b102-v6-11-k2","title":"責任邊界","titleEn":"Responsibility boundaries","text":"驗證證據與運行授權由不同角色承擔時，介面必須清楚。","textEn":"Interfaces must be explicit when verification and operating authority belong to different roles."}],"quiz":{"options":["直接填寫已全面復歸","機械完成與功能未驗證分別列示","刪除測試欄以免混淆"],"optionsEn":["Mark fully restored","Record mechanical completion and unverified function separately","Remove the test field"],"answer":1,"question":"工件已裝回但功能測試未完成，交接表應如何表示？","questionEn":"A component is reinstalled but functional testing is incomplete. How should it be recorded?","explanation":"不同完成層次不能互相替代，否則會掩蓋未結案工作。","explanationEn":"Different completion levels are not interchangeable and must not hide unfinished work."}},{"id":"b102-v6-12","sequence":12,"order":4,"sourceIds":["v6-channel-infrastructure","v6-channel-tbm","v6-channel-construction"],"simulationOnly":true,"estimatedMinutes":20,"prerequisiteIds":["b102-v6-11"],"title":"交付三隧道整合模型","titleEn":"Deliver the integrated three-bore model","objective":"將土建與機電證據連成可查核的系統。","objectiveEn":"Connect civil and service-system evidence into an auditable model.","instruction":"把地質、襯砌、漏水、通風和供電圖表整理成同一介面索引。選一個「供電中斷伴隨滲水」假想情境，指出需聯合查證的兩個系統與資料缺口。","instructionEn":"Index ground, lining, ingress, ventilation and power records together. For an invented power-loss-plus-ingress scenario, identify two systems requiring joint review and remaining evidence gaps.","observation":"檢查每個功能主張是否有可定位的圖表或紀錄支持。","observationEn":"Check that each functional claim has a located diagram or record behind it.","failure":"各專業圖表單獨完整，卻無法對齊區段名稱與狀態。","failureEn":"Individually complete discipline records cannot be reconciled by location or state.","check":"提交共享區段索引、假設清單與至少三項未解介面問題。","checkEn":"Submit a common section index, assumptions and at least three unresolved interface questions.","knowledge":[{"id":"b102-v6-12-k1","title":"系統整合","titleEn":"Systems integration","text":"隧道能否服務取決於土建、設備、交通與維護的共同狀態。","textEn":"Tunnel service depends on combined civil, equipment, traffic and maintenance states."},{"id":"b102-v6-12-k2","title":"共同識別","titleEn":"Common identifiers","text":"一致的區段與設備識別可防止把不同位置的證據錯接。","textEn":"Consistent section and equipment identifiers prevent mismatching evidence from different locations."}],"quiz":{"options":["只核對總設備數量是否相同","只比較各自最後一次正常結果","區段、設備識別、時間及狀態"],"optionsEn":["Whether total equipment counts match","Compare only each system’s latest normal result","Section, equipment identity, time and state"],"answer":2,"question":"整合兩份排水與供電紀錄前，最先應核對什麼？","questionEn":"What should first be reconciled when integrating drainage and power records?","explanation":"共同識別與時間狀態使不同專業證據可以正確連結。","explanationEn":"Shared identifiers and time/state information allow evidence from different disciplines to be connected correctly."}}],"title":"機電整合與交付","titleEn":"Systems integration and handover","description":"以桌上情境檢查通風、供電、交通和維護的依賴。","descriptionEn":"Use tabletop scenarios to review dependencies among ventilation, power, traffic and maintenance."}],"title":"英法海底隧道","titleEn":"Channel Tunnel","summary":"從白堊泥灰岩選線到三隧道營運系統，練習地質推論、支承、防水與機電整合。","summaryEn":"Study geological inference, support, water control and systems integration from chalk-marl alignment to three-bore operation.","scope":"以公開資料建立的原創教學分解；所有步驟為紙上、數位模型與證據判讀練習。自繪的示意與自設資料必須標示假設；本站未提供現地工程資料，亦不是核准施工、設備操作或水質放行程序。","scopeEn":"Original educational decomposition of public information. Every step is a paper, digital-model or evidence-interpretation exercise. Label assumptions in self-drawn diagrams and invented data; this site does not supply field engineering records or approved construction, operating or water-release procedures.","diagram":{"type":"tunnel","labels":["地層","開挖與襯砌","聯絡通道","機電","監測"],"labelsEn":["Ground","Excavation and lining","Cross-passages","Services","Monitoring"],"original":true,"notToScale":true},"stepCount":12,"estimatedMinutes":240,"curriculumVersion":6}};
